package dev.blossom;
import dev.blossom.core.*;
import java.nio.file.*;
import java.util.*;
import java.awt.image.BufferedImage;
import javax.imageio.ImageIO;
public final class CoreTest {
    private static int checks;
    private static void check(boolean ok,String message){checks++;if(!ok)throw new AssertionError(message);}
    public static void main(String[] args)throws Exception {
        check(PerformanceSettings.workers(0,1)==1&&PerformanceSettings.workers(0,32)==4&&PerformanceSettings.workers(0,4)==2,"automatic workers bounded by buffer pool");
        check(PerformanceSettings.workers(9,8)==4,"manual workers bounded");
        PerformanceSettings perf=new PerformanceSettings();Properties perfProps=new Properties();perf.chunkWorkers=3;perf.chunkBudgetMs=4;perf.modelBatching=false;perf.save(perfProps);perf=new PerformanceSettings();perf.load(perfProps);
        check(perf.chunkWorkers==3&&perf.chunkBudgetMs==4&&!perf.modelBatching,"performance choices survive restart");
        FrameCapture frames=new FrameCapture();frames.record(0);frames.record(-1);frames.record(10000000);frames.record(1000000000);
        check(frames.size()==2&&frames.copy()[1]==1000000000,"capture retains one-second stalls and rejects invalid intervals");
        String captureSummary=FrameCapture.summary(frames.copy());check(captureSummary.contains("1% low FPS: 1.00")&&captureSummary.contains("Worst ms: 1000.000"),"slow-tail report includes stalls");
        check(FrameCapture.summary(new long[]{10000000,10000000}).contains("Average FPS: 100.00"),"capture mean frame rate");
        BenchmarkTest.run();
        LegacySettings legacy=new LegacySettings();check(!legacy.enabled[10],"always swing is opt-in");
        Properties legacyProps=new Properties();for(int i=0;i<legacy.enabled.length;i++)legacy.enabled[i]=(i%2==0);legacy.save(legacyProps);
        LegacySettings legacyRestored=new LegacySettings();legacyRestored.load(legacyProps);for(int i=0;i<legacy.enabled.length;i++)check(legacyRestored.enabled[i]==legacy.enabled[i],"independent legacy option roundtrip "+i);
        check(SettingsPages.move(1,9,5,-1)==0,"previous settings page");
        check(SettingsPages.move(1,9,5,1)==0,"last settings page wraps");
        check(SettingsPages.move(0,9,5,-1)==1,"first settings page wraps backward");
        ClientSettings emptyPotions=new ClientSettings();check(!emptyPotions.showEmptyPotions,"empty potion HUD hidden by default");
        Properties potionConfig=new Properties();emptyPotions.showEmptyPotions=true;emptyPotions.save(potionConfig);emptyPotions=new ClientSettings();emptyPotions.load(potionConfig);check(emptyPotions.showEmptyPotions,"empty potion preference persists");
        check(VisualSettings.category(39)==10&&VisualSettings.category(35)==11&&VisualSettings.category(6)==9,"particle mapping uses actual vanilla IDs");
        ClientSettings tilt=new ClientSettings();Properties tiltProps=new Properties();tilt.hitTilt=0;tilt.save(tiltProps);tilt=new ClientSettings();tilt.load(tiltProps);check(tilt.hitTilt==0,"zero hit tilt survives restart");
        LatencyState latency=new LatencyState();Object local=new Object(),server=new Object();latency.update(local,true,0);check(latency.value()==0,"local ping is zero");latency.update(server,false,0);check(latency.value()==-1,"server transition discards local zero");latency.update(server,false,179);check(latency.value()==179,"server latency updates without toggle");latency.update(new Object(),false,0);check(latency.value()==-1,"reconnect resets latency");latency.clear();check(latency.value()==-1,"disabled latency released");
        Class.forName("dev.blossom.integration.BlossomDisabledModulesTest").getMethod("run").invoke(null);
        ClothTest.run();
        ClickWindow clicks=new ClickWindow();clicks.click(100);clicks.click(200);
        check(clicks.count(1099,1000)==2,"rolling timestamps");check(clicks.count(1100,1000)==1,"boundary expiration");
        check(clicks.count(10000,1000)==0,"idle expires clicks");
        for(int i=0;i<5000;i++)clicks.click(i);check(clicks.count(5000,10000)==4096,"bounded input storage");
        FrameStats f=new FrameStats(1000);for(int i=0;i<990;i++)f.record(10000000);for(int i=0;i<10;i++)f.record(50000000);
        double[] s=f.snapshot();check(Math.abs(s[0]-96.153846)<.001,"mean frame duration FPS");
        check(s[1]==20&&s[2]==20,"slow tail averages");check(s[3]==10,"median ms");
        Timeline t=new Timeline(new int[]{100,200,100},true);
        check(t.frame(0,true)==0,"first frame");check(t.frame(100000000,true)==1,"exact boundary");
        check(t.frame(400000000,true)==1,"ping pong reverse");check(t.frame(600000000,true)==0,"ping pong loop");
        check(t.frame(Long.MAX_VALUE,false)==1,"non looping holds last");
        boolean rejected=false;try{new Timeline(new int[]{0},false);}catch(IllegalArgumentException e){rejected=true;}check(rejected,"bad timing");
        Path dir=Files.createTempDirectory("blossom-test");ProfileStore store=new ProfileStore(dir);
        Properties p=new Properties();p.setProperty("cape","pink");store.save("default",p);
        check(store.load("default").getProperty("cape").equals("pink"),"profile roundtrip");
        p.setProperty("cape","new");store.save("default",p);check(Files.exists(dir.resolve("default.backup")),"retained backup");
        p.setProperty("x","NaN");check(ProfileStore.fraction(p,"x",.5f)==.5f,"nonfinite rejected");
        rejected=false;try{store.load("../escape");}catch(IllegalArgumentException e){rejected=true;}check(rejected,"path traversal rejected");
        EventBus<Integer> bus=new EventBus<Integer>();int[] count={0};
        bus.subscribe(v->{throw new IllegalStateException();});AutoCloseable sub=bus.subscribe(v->count[0]+=v);bus.post(3);sub.close();bus.post(5);check(count[0]==3,"listener isolation and unsubscribe");
        Modules modules=new Modules();modules.add("a","A","HUD","test",true,0);check(modules.on("a"),"module enable");modules.get("a").enabled=false;check(!modules.on("a"),"module disable");
        Path image=dir.resolve("cape.png");ImageIO.write(new BufferedImage(64,96,BufferedImage.TYPE_INT_ARGB),"png",image.toFile());
        CapeFrames cape=CapeFrames.load(image);check(cape.images.length==3,"vertical sheet frames");
        ImageIO.write(new BufferedImage(63,32,BufferedImage.TYPE_INT_ARGB),"png",image.toFile());
        rejected=false;try{CapeFrames.load(image);}catch(java.io.IOException e){rejected=true;}check(rejected,"invalid cape dimensions");
        PlaybackClock clock=new PlaybackClock(0);check(clock.elapsed(100)==100,"clock runs");clock.paused(true,100);check(clock.elapsed(500)==100,"pause holds");
        clock.speed(2,600);clock.paused(false,700);check(clock.elapsed(800)==300,"speed and resume continuity");clock.restart(900);check(clock.elapsed(950)==100,"restart retains speed");
        ImageIO.write(new BufferedImage(192,32,BufferedImage.TYPE_INT_ARGB),"png",image.toFile());
        check(CapeFrames.load(image).images.length==3,"horizontal spritesheet");
        CapeLibrary library=new CapeLibrary(dir.resolve("library"));String imported=library.importEntry(image);
        check(library.list().contains(imported),"validated staged import");String duplicate=library.importEntry(image);check(!duplicate.equals(imported),"imports never overwrite");
        String renamed=library.rename(imported,"pink");check(renamed.equals("pink.png"),"rename preserves PNG extension");library.trash(renamed);check(!library.list().contains(renamed),"remove moves out of active library");
        try(java.util.stream.Stream<Path> trash=Files.list(dir.resolve("library/.trash"))){check(trash.count()==1,"removed artwork is recoverable");}
        rejected=false;try{library.entry("../escape");}catch(IllegalArgumentException e){rejected=true;}check(rejected,"cape traversal rejected");
        try(java.util.stream.Stream<Path> files=Files.walk(dir)){for(Path path:(Iterable<Path>)files.sorted(Comparator.reverseOrder())::iterator)Files.delete(path);}
        ToggleLatch latch=new ToggleLatch();latch.press();check(latch.active(),"toggle on");latch.press();check(!latch.active(),"toggle off");latch.press();latch.reset();check(!latch.active(),"menu reset");
        check(HudLayout.position(.5f,100,20)==40,"normalized available width");check(HudLayout.position(1,10,20)==0,"oversized widget");
        check(HudLayout.fraction(40,100,20)==.5f,"drag geometry roundtrip");check(HudLayout.snap(3,100,20,false)==0,"edge snapping");
        ClientSettings settings=new ClientSettings();Properties values=new Properties();values.setProperty("zoom.factor","NaN");values.setProperty("crosshair.length","900");settings.load(values);
        check(settings.zoomFactor==4&&settings.crosshairLength==20,"settings bounds and NaN");
        settings.crosshairColor=0x8099aabb;settings.save(values);ClientSettings restored=new ClientSettings();restored.load(values);check(restored.crosshairColor==0x8099aabb,"ARGB roundtrip");
        modules.get("a").scale=2;modules.get("a").saveStyle(values);modules.get("a").resetLayout();modules.get("a").loadStyle(values);check(modules.get("a").scale==2,"HUD style roundtrip");
        ClientSettings defaults=new ClientSettings();defaults.load(new Properties());
        check(!defaults.fpsAverage&&!defaults.fpsLows,"current FPS is the default for new and existing profiles");
        defaults.fpsAverage=true;defaults.fpsLows=true;Properties fpsValues=new Properties();defaults.save(fpsValues);ClientSettings fpsRestored=new ClientSettings();fpsRestored.load(fpsValues);
        check(fpsRestored.fpsAverage&&fpsRestored.fpsLows,"FPS behavior settings persist");
        check(FpsDisplay.format(165,s,false,false).equals("165 FPS"),"current FPS uses vanilla counter, not historical average");
        check(FpsDisplay.format(165,s,true,false).equals("96 FPS (average)"),"average FPS selection");
        check(FpsDisplay.format(165,s,false,true).contains("1% 20"),"slow-frame statistics optional");
        ToggleLatch persistent=new ToggleLatch();persistent.press();persistent.context(true,true,true);
        check(persistent.active()&&!persistent.requested(true),"sprint remembers toggle but pauses in menu");
        persistent.context(true,false,true);check(persistent.requested(false),"sprint resumes after menu");persistent.context(false,false,true);check(persistent.active(),"world changes preserve sprint");persistent.context(false,true,true);check(persistent.active()&&!persistent.requested(true),"disconnect keeps latch but menu pauses input");persistent.set(true);persistent.press();check(!persistent.active(),"only another press toggles sprint off");
        SmoothZoom zoom=new SmoothZoom();check(zoom.update(true,4,0)==1,"zoom starts without a jump");
        check(Math.abs(zoom.update(true,4,40000000)-.625)<.0001,"zoom FOV ratio lerps at halfway");
        check(zoom.update(true,4,80000000)==.25,"zoom reaches target in 80 ms");
        zoom.scroll(1,80000000);check(zoom.value(80000000)==.25,"scroll starts continuously");
        check(Math.abs(zoom.value(160000000)-.2)<.0001,"scroll target interpolates");
        zoom.update(false,4,160000000);check(zoom.value(240000000)==1,"zoom release interpolates to normal");
        zoom.update(true,4,240000000);check(zoom.factor()==4&&zoom.value(320000000)==.25,"new hold resets scroll level");
        zoom.reset();check(zoom.value(1000000000)==1,"world reset clears zoom");
        FovSettings fov=new FovSettings();check(fov.calculate(true,2,true,true,1)==70,"constant FOV ignores all conditions");
        fov.setConstant(false);check(fov.calculate(true,0,false,false,0)==80,"sprint FOV override");
        check(fov.calculate(false,2,false,false,0)==90,"speed II override");
        check(fov.calculate(false,2,true,false,0)==60,"slowness takes precedence over speed");
        check(fov.calculate(false,0,false,true,0)==80,"flight override");
        check(fov.calculate(false,0,false,false,1)==55,"fully drawn bow FOV");
        check(!fov.constant&&fov.dynamicSprint,"dynamic mode excludes static");fov.setConstant(true);check(fov.constant&&!fov.dynamicSprint,"static mode excludes dynamic");fov.setConstant(false);
        Properties fovProperties=new Properties();fov.base=95;fov.save(fovProperties);FovSettings loadedFov=new FovSettings();loadedFov.load(fovProperties);check(loadedFov.base==95&&!loadedFov.constant,"FOV settings persist");
        check(HudText.compact("ping","0 ms (server)").equals("0"),"compact ping");
        check(HudText.compact("cps","0 | 0 CPS").equals("0 | 0"),"compact CPS");
        check(HudText.potionLevel(0,true).isEmpty()&&HudText.potionLevel(1,true).equals(" 2")&&HudText.potionLevel(0,false).equals(" 1"),"optional level one without losing higher potion levels");
        Modules all=new Modules();all.add("fps","FPS","HUD","",true,0);all.add("ping","Ping","HUD","",false,.3f);all.add("zoom","Zoom","Visual","",true,0);
        Modules.Module source=new Modules.Module("style","Style","HUD","",true,0);source.scale=2;all.applyVisual("scale",source);
        check(all.get("fps").scale==2&&all.get("ping").scale==2&&all.get("zoom").scale==1,"global visuals affect enabled and disabled HUDs only");
        check(all.get("ping").y==.3f&&!all.get("ping").enabled,"global style preserves layout and enablement");
        all.get("fps").extraText=false;Properties compactProfile=new Properties();all.get("fps").saveStyle(compactProfile);all.get("fps").extraText=true;all.get("fps").loadStyle(compactProfile);check(!all.get("fps").extraText,"compact text persists per module");
        System.out.println("Core tests passed: "+checks);
    }
}
